solution.solution.py:
PAGE_SIZE = 4096

def split(address):
    return (address // PAGE_SIZE, address % PAGE_SIZE)

def translate(address, page_table):
    page, offset = split(address)
    if page not in page_table:
        return None
    return page_table[page] * PAGE_SIZE + offset

unitTests:
@test("splitting addresses")
def _():
    check_eq(split(0x3A7C), (0x3, 0xA7C))
    check_eq(split(4095), (0, 4095))
    check_eq(split(4096), (1, 0))
    check_eq(split(0x7FFE1234), (0x7FFE1, 0x234))

@test("translation keeps the offset")
def _():
    table = {3: 0x51, 0: 7, 0x7FFE1: 0x2A}
    check_eq(translate(0x3A7C, table), 0x51A7C)
    check_eq(translate(0x10, table), 7 * 4096 + 0x10)
    check_eq(translate(0x7FFE1234, table), 0x2A234)

@test("page faults")
def _():
    check_eq(translate(0, {}), None)
    check_eq(translate(0x5000, {3: 1}), None)

